// Validate decision input. Ranked comparisons required; offers/vendors may be empty (→ INSUFFICIENT_DATA, never invented).
const i = $input.first().json;
if (!i.procurement_id) throw new Error('Missing procurement_id');
if (!i.procurement) throw new Error('Missing procurement record');
return [{ json: { procurement_id: i.procurement_id, trace_id: i.trace_id, procurement: i.procurement, ranked: i.ranked ?? [], offersByProduct: i.offersByProduct ?? {}, vendorsById: i.vendorsById ?? {}, productsById: i.productsById ?? {}, mandatory: i.mandatory ?? {} } }];

// DETERMINISTIC gates (canonical: tools/_lib/decision.js). Scans ranks in order; NOTHING invented.
// Unverified mandatory specs block; verified violations skip the candidate; no offers/prices/contact -> INSUFFICIENT_DATA.
const inp = $input.first().json;
const num = (v) => (typeof v === 'number' && !Number.isNaN(v) ? v : null);
const isMissing = (v) => v === null || v === undefined || (typeof v === 'string' && (v.trim().toLowerCase() === 'unavailable' || v.trim() === ''));
const explain = (decision, row, reason, blocking, offer) => ({ decision, product_id: row ? row.product_id : null, comparison_id: row && row.comparison_id ? row.comparison_id : null, decision_reason: reason, blocking_reasons: blocking, criteria_used: (row && row.criteria_used) || [], criteria_missing: (row && row.criteria_missing) || [], evidence_urls: (row && row.evidence_urls) || [], _offer: offer ? { offer_id: offer.offer_id, vendor_id: offer.vendor_id, net_price: offer.net_price, currency: offer.currency } : null });
const mandatoryFailed = (specs, mandatory) => { const failed = [], unver = []; const lower = Object.fromEntries(Object.entries(specs || {}).map(([k, v]) => [String(k).toLowerCase(), v])); for (const [f, rule] of Object.entries(mandatory || {})) { const v = lower[f.toLowerCase()]; if (isMissing(v)) { unver.push(f); continue; } if (rule && typeof rule.min === 'number' && num(v) !== null && num(v) < rule.min) failed.push(f + '=' + v + ' below minimum ' + rule.min); if (rule && typeof rule.max === 'number' && num(v) !== null && num(v) > rule.max) failed.push(f + '=' + v + ' above maximum ' + rule.max); } return { failed, unver }; };
const { procurement, ranked, offersByProduct, vendorsById, productsById, mandatory } = inp;
if (!ranked.length) return [{ json: { procurement_id: inp.procurement_id, decision: 'INSUFFICIENT_DATA', product_id: null, comparison_id: null, decision_reason: 'No ranked candidates available for decision.', blocking_reasons: ['no ranked candidates'], criteria_used: [], criteria_missing: [], evidence_urls: [] } }];
const caseCcy = procurement.currency ? String(procurement.currency).toUpperCase() : null;
const budget = num(procurement.budget);
let rank1 = null, rank1blocking = null, blockedOthers = 0;
for (const row of ranked) {
  const product = productsById[row.product_id] || {};
  const blocking = [];
  if (row.overall_score === null || row.overall_score === undefined) blocking.push('no scoring basis (overall_score null)');
  const mc = mandatoryFailed(product.specifications, mandatory);
  if (mc.failed.length) { if (row.rank === 1) { rank1 = row; rank1blocking = mc.failed.map((f) => 'mandatory_failed:' + f); } else blockedOthers++; continue; }
  if (mc.unver.length) blocking.push(...mc.unver.map((f) => 'mandatory_unverifiable:' + f));
  const offers = (offersByProduct[row.product_id] || []).filter((o) => num(o.net_price) !== null && num(o.net_price) > 0 && o.currency);
  const sameCcy = caseCcy ? offers.filter((o) => String(o.currency).toUpperCase() === caseCcy) : [];
  if (!offers.length) blocking.push('no verified offers');
  else if (caseCcy && !sameCcy.length) blocking.push('no currency-compatible offer (no FX source)');
  const withContact = sameCcy.filter((o) => vendorsById[o.vendor_id] && vendorsById[o.vendor_id].contact_channel && vendorsById[o.vendor_id].contact_channel.status !== 'UNAVAILABLE');
  if (offers.length && !withContact.length) blocking.push('no vendor contact channel');
  if (blocking.length) {
    if (row.rank === 1) { rank1 = row; rank1blocking = blocking; }
    else blockedOthers++;
    continue;
  }
  const best = Math.min(...sameCcy.map((o) => o.net_price));
  const bestOffer = sameCcy.find((o) => o.net_price === best);
  const qty = (Number.isInteger(procurement.quantity) && procurement.quantity > 0) ? procurement.quantity : null; const totalEst = (qty !== null) ? best * qty : null; if (budget !== null && qty !== null && totalEst !== null && totalEst > budget) return [{ json: { procurement_id: inp.procurement_id, ...explain('NEGOTIATE', row, 'Verified total estimate ' + totalEst + ' ' + caseCcy + ' (unit ' + best + ' x ' + qty + ') exceeds total budget ' + budget + ' ' + caseCcy + '; a real vendor channel exists, negotiation is legitimate.', [], bestOffer) } }];
  return [{ json: { procurement_id: inp.procurement_id, ...explain('PROCEED', row, 'Sufficient verified evidence; best verified price ' + best + ' ' + caseCcy + (budget !== null ? ' within budget ' + budget + ' ' + caseCcy : '') + '; no blocking issue.', [], bestOffer) } }];
}
const top = rank1 || ranked[0];
const blockingFinal = [...(rank1blocking || ['no candidate clears gates']), ...(blockedOthers ? [blockedOthers + ' lower-ranked candidate(s) also blocked'] : [])];
return [{ json: { procurement_id: inp.procurement_id, ...explain('INSUFFICIENT_DATA', top, rank1blocking ? 'Top candidate cannot support a reliable decision: ' + rank1blocking.join('; ') + '.' : 'No ranked candidate clears mandatory and evidence gates.', blockingFinal) } }];

// Enforce decision-output schema: enum, reason present, traceable evidence.
const o = $input.first().json?.output ?? $input.first().json;
if (!['PROCEED','NEGOTIATE','INSUFFICIENT_DATA'].includes(o.decision)) throw new Error('bad decision: ' + o.decision);
if (!o.decision_reason) throw new Error('missing decision_reason');
if (!Array.isArray(o.blocking_reasons)) throw new Error('blocking_reasons must be array');
return [{ json: { procurement_id: o.procurement_id, product_id: o.product_id ?? null, comparison_id: o.comparison_id ?? null, decision: o.decision, decision_reason: o.decision_reason, blocking_reasons: o.blocking_reasons, criteria_used: o.criteria_used ?? [], criteria_missing: o.criteria_missing ?? [], evidence_urls: o.evidence_urls ?? [], _offer: o._offer ?? null } }];
